package com.leotechnologies.tests;

import com.leotechnologies.tests.core.SiteConfig;
import com.leotechnologies.tests.core.Versions;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.Proxy;
import java.net.ProxySelector;
import java.net.Socket;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.cert.X509Certificate;
import java.time.Duration;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLSocket;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;

/**
 * The audit tests' checks, each asking the site once: by HTTP (Java's client, redirects not followed; a path on
 * the suite's base address, the audited site's own address whole on the base address's host), a handshake, or a socket.
 * Each
 * says what it saw: open, fixed or cannot, and in words. Audit.java's hold() runs one and decides how the test ends.
 */
final class AuditChecks {
    private static final HttpClient HTTP = HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER)
            .connectTimeout(Duration.ofSeconds(15)).build();
    private final String kind;
    private final String address;
    private final String open;
    private final String ip;
    private final int port;
    private final int atLeast;
    private final String header;
    private final String lists;
    private final int days;

    /** One item's check: its kind, what it asks, and what keeps the item open (Audit.Item's steps). */
    AuditChecks(String kind, String address, String open, String ip, int port, int atLeast, String header,
            String lists, int days) {
        this.kind = kind;
        this.address = address;
        this.open = open;
        this.ip = ip;
        this.port = port;
        this.atLeast = atLeast;
        this.header = header;
        this.lists = lists;
        this.days = days;
    }

    /** What the check saw: open, fixed or cannot, and in words. */
    String[] look() {
        try {
            return switch (kind) {
                case "status" -> open.equals("page") ? pageSeen() : statusSeen();
                case "hops" -> hopsSeen();
                case "chain" -> chainSeen();
                case "header" -> headerSeen();
                case "file" -> fileSeen();
                case "certificate" -> Certificates.seen(address, port, open, days);
                case "socket" -> socketSeen();
                default -> new String[] {"cannot", "no check named for it"};
            };
        } catch (IOException e) {
            return new String[] {"cannot", "the check failed: " + e.getMessage()};
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return new String[] {"cannot", "the run was stopped"};
        }
    }

    private String[] statusSeen() throws InterruptedException {
        HttpResponse<Void> answer;
        try {
            answer = ask(address);
        } catch (IOException e) {
            String why = "gave no answer (" + e.getClass().getSimpleName() + ")";
            if (open.equals("gone")) return goneUnanswered(e, why);
            return new String[] {open.equals("redirect") || open.equals("twin") ? "cannot" : "open", why};
        }
        int status = answer.statusCode();
        String to = answer.headers().firstValue("location").orElse("");
        String said = "answered " + status + (to.isEmpty() ? "" : " to " + to);
        if (open.equals("twin")) return twinSeen(status, said);
        return switch (open) {
            case "broken" -> new String[] {Audit.broken(status) ? "open" : status >= 400 ? "cannot" : "fixed",
                    status >= 400 && !Audit.broken(status) ? said
                    + ", which the audit does not call broken (a sign-in or a bot wall?)" : said};
            case "redirect" -> new String[] {status >= 400 ? "cannot" : status >= 300
                    && within(answer.uri(), to) ? "open" : "fixed", said};
            case "not-to-https" -> new String[] {status >= 300 && status < 400 && to.toLowerCase(Locale.ROOT)
                    .startsWith("https:") ? "fixed" : "open", said};
            // Another site's address (SITE-33), by the crawl's rule: gone while 404 or 410; any answer below 400 is a
            // page again.
            case "gone" -> new String[] {status == 404 || status == 410 ? "open" : status < 400 ? "fixed" : "cannot",
                    status >= 400 && status != 404 && status != 410 ? said
                    + ", which the audit does not call gone (a bot wall?)" : said};
            default -> new String[] {"cannot", "no such check: " + open};
        };
    }

    /**
     * Another site's address that gave no answer: gone while its name does not resolve or nothing takes the connection;
     * a timeout cannot say.
     */
    private static String[] goneUnanswered(IOException e, String why) {
        Throwable cause = e;
        while (cause.getCause() != null) cause = cause.getCause();
        boolean gone = e instanceof java.net.ConnectException || cause instanceof java.net.UnknownHostException
                || cause instanceof java.net.ConnectException;
        return new String[] {gone ? "open" : "cannot", why};
    }

    private String[] hopsSeen() throws IOException, InterruptedException {
        String at = address;
        for (int hop = 0; hop < 10; hop++) {
            HttpResponse<Void> answer = ask(at);
            String to = answer.headers().firstValue("location").orElse("");
            if (answer.statusCode() < 300 || answer.statusCode() >= 400 || to.isEmpty()) return new String[] {"fixed",
                    "no hop leaves https (" + answer.statusCode() + " at " + answer.uri() + ")"};
            URI next = answer.uri().resolve(to);
            if ("http".equalsIgnoreCase(next.getScheme())) return new String[] {"open", "redirects to " + next};
            at = next.toString();
        }
        return new String[] {"cannot", "more than 10 redirects"};
    }

    /**
     * The site's other name: open while it answers 2xx itself; a move sends visitors on; any other answer cannot say.
     */
    private static String[] twinSeen(int status, String said) {
        if (status >= 200 && status < 300) return new String[] {"open", said + " itself"};
        return new String[] {status >= 300 && status < 400 ? "fixed" : "cannot", said};
    }

    /** One header of one page: what it sends, against what keeps the item open. */
    private String[] headerSeen() throws IOException, InterruptedException {
        HttpResponse<Void> answer = ask(address);
        if (answer.statusCode() >= 300) return new String[] {"cannot", "answered " + answer.statusCode()
                + ": not the page whose headers the crawl read"};
        String value = answer.headers().firstValue(header).orElse(null);
        return switch (open) {
            case "absent" -> value == null ? new String[] {"open", "sends no " + header} : new String[] {"fixed",
                    "sends " + header + ": " + value};
            case "unframed" -> {
                String policy = answer.headers().firstValue("content-security-policy").orElse("");
                boolean guarded = value != null || policy.toLowerCase(Locale.ROOT).contains("frame-ancestors");
                yield guarded ? new String[] {"fixed", value != null ? "sends " + header + ": "
                        + value : "sends a Content-Security-Policy with frame-ancestors"} : new String[] {"open",
                        "sends neither " + header + " nor frame-ancestors"};
            }
            case "versioned" -> value != null
                    && Versions.announced(value) ? new String[] {"open", header + " says "
                    + value} : new String[] {"fixed", value == null ? "sends no " + header : header + " says " + value
                    + ", no version"};
            default -> new String[] {"cannot", "no such check: " + open};
        };
    }

    /** A file the site publishes, read: the sitemap, an address it lists, or security.txt. */
    private String[] fileSeen() throws InterruptedException {
        HttpResponse<String> file;
        try {
            file = read(address);
        } catch (IOException e) {
            return new String[] {open.equals("lists") ? "cannot" : "open", "gave no answer (" + e.getClass()
                    .getSimpleName() + ")"};
        }
        int status = file.statusCode();
        String body = status < 300 ? file.body() : "";
        return switch (open) {
            case "no-sitemap" -> {
                int listed = locs(body).size();
                yield status >= 300 ? new String[] {"open", "answered " + status} : listed == 0 ? new String[] {"open",
                        "answers " + status + ", listing no address"} : new String[] {"fixed", "answers " + status
                        + ", listing " + listed + " address" + (listed == 1 ? "" : "es")};
            }
            case "no-contact" -> status != 200 ? new String[] {"open", "answered " + status} : contactLine(
                    body) ? new String[] {"fixed", "answers 200, with a Contact line"} : new String[] {"open",
                    "answers 200, with no Contact line"};
            case "lists" -> status >= 300 ? new String[] {"cannot", "the sitemap answered " + status
                    + ": it cannot say what it lists"} : listedSeen(body);
            default -> new String[] {"cannot", "no such check: " + open};
        };
    }

    /**
     * One canonical link of a page (SITE-12), as the browser resolved it (AuditPages.canonical), by the crawl's rule:
     * open while it
     * names another site, or an address of the site that answers 400 or more or redirects elsewhere; fixed when it
     * names the page
     * itself, or one that answers.
     */
    static String[] canonicalSeen(String address, String canonical) {
        String named = asked(canonical);
        if (!named.startsWith("/")) return new String[] {"open", "its canonical names another site: " + canonical};
        if (named.equals(address)) return new String[] {"fixed", "its canonical names the page itself"};
        try {
            HttpResponse<Void> answer = ask(named);
            int status = answer.statusCode();
            if (status >= 400) return new String[] {"open", "its canonical " + named + " answers " + status};
            if (status >= 300) return new String[] {"open", "its canonical " + named + " redirects (" + status + ")"};
            return new String[] {"fixed", "its canonical " + named + " answers " + status};
        } catch (IOException e) {
            return new String[] {"cannot", "its canonical " + named + " gave no answer (" + e.getClass()
                    .getSimpleName() + ")"};
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return new String[] {"cannot", "the run was stopped"};
        }
    }

    /** Whether the sitemap still lists the address, and what that address answers. */
    private String[] listedSeen(String sitemap) throws InterruptedException {
        boolean listed = locs(sitemap).stream().anyMatch(loc -> asked(loc).equals(lists));
        if (!listed) return new String[] {"fixed", "the sitemap no longer lists " + lists};
        try {
            HttpResponse<Void> answer = ask(lists);
            int status = answer.statusCode();
            return status >= 300 ? new String[] {"open", "the sitemap lists it, and it answered "
                    + status} : new String[] {"fixed", "the sitemap lists it, and it answers " + status};
        } catch (IOException e) {
            return new String[] {"cannot", "the sitemap lists it, and it gave no answer (" + e.getClass()
                    .getSimpleName() + ")"};
        }
    }

    /**
     * An address that cannot exist, its redirects followed as the crawl did (5): open while it ends below 300, fixed on
     * a not-found status.
     */
    private String[] pageSeen() throws IOException, InterruptedException {
        String at = address;
        for (int hop = 0; ; hop++) {
            HttpResponse<Void> answer = ask(at);
            int status = answer.statusCode();
            String to = answer.headers().firstValue("location").orElse("");
            if (status >= 300 && status < 400 && !to.isEmpty() && hop < 5) {
                at = answer.uri().resolve(to).toString();
                continue;
            }
            String said = "answered " + status + (hop > 0 ? " after " + hop + " redirect" + (hop == 1 ? "" : "s") : "");
            if (status < 300) return new String[] {"open", said};
            return Audit.broken(status) ? new String[] {"fixed", said} : new String[] {"cannot", said
                    + ", which the audit does not call a not-found answer"};
        }
    }

    /** Redirects followed one by one, counted: open while there are atLeast of them or more. */
    private String[] chainSeen() throws IOException, InterruptedException {
        String at = address;
        List<String> hops = new ArrayList<>();
        for (int hop = 0; hop < 10; hop++) {
            HttpResponse<Void> answer = ask(at);
            int status = answer.statusCode();
            String to = answer.headers().firstValue("location").orElse("");
            if (status < 300 || status >= 400 || to.isEmpty()) {
                String said = hops.size() + " redirect" + (hops.size() == 1 ? "" : "s")
                        + (hops.isEmpty() ? "" : " (" + String.join(", ", hops) + ")") + ", then " + status;
                if (hops.size() >= atLeast) return new String[] {"open", said};
                return status >= 400 ? new String[] {"cannot", said} : new String[] {"fixed", said};
            }
            hops.add(String.valueOf(status));
            at = answer.uri().resolve(to).toString();
        }
        return new String[] {"cannot", "more than 10 redirects"};
    }

    private String[] socketSeen() {
        if (behindProxy()) return new String[] {"cannot", "behind a proxy: the run reaches the site through it"};
        try (Socket s = new Socket()) {
            s.connect(new InetSocketAddress(ip, port), 5000);
            return new String[] {"fixed", ip + ":" + port + " takes a connection"};
        } catch (IOException e) {
            return new String[] {"open", ip + ":" + port + " takes no connection (" + e.getClass().getSimpleName()
                    + ")"};
        }
    }

    /**
     * A sitemap's addresses, as the crawl read them: each <loc> (any case), its address between spaces alone, then
     * </loc>; its &amp; undone.
     */
    static List<String> locs(String sitemap) {
        List<String> out = new ArrayList<>();
        for (int at = 0; at < sitemap.length(); at++) {
            if (!sitemap.regionMatches(true, at, "<loc>", 0, 5)) continue;
            int from = spaces(sitemap, at + 5);
            int to = from;
            while (to < sitemap.length() && sitemap.charAt(to) != '<' && !space(sitemap.charAt(to))) to++;
            int close = spaces(sitemap, to);
            if (to == from || !sitemap.regionMatches(true, close, "</loc>", 0, 6)) continue;
            out.add(sitemap.substring(from, to).replace("&amp;", "&"));
            at = close + 5;
        }
        return out;
    }

    /**
     * Whether a security.txt has a Contact line: a line that starts "contact:" (any case), after spaces or blank lines.
     */
    static boolean contactLine(String body) {
        for (int at = 0; at < body.length(); at++) {
            boolean lineStart = at == 0 || lineEnd(body.charAt(at - 1))
                    && !(body.charAt(at - 1) == '\r' && body.charAt(at) == '\n');
            if (lineStart && body.regionMatches(true, spaces(body, at), "contact:", 0, 8)) return true;
        }
        return false;
    }

    /** Where a run of spaces, tabs and line ends starting at `at` ends. */
    private static int spaces(String text, int at) {
        while (at < text.length() && space(text.charAt(at))) at++;
        return at;
    }

    /** A space, a tab, or a line end: the white space a sitemap's <loc> and a Contact line may have around them. */
    private static boolean space(char c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\u000B' || c == '\f' || c == '\r';
    }

    /** A character that ends a line. */
    private static boolean lineEnd(char c) {
        return c == '\n' || c == '\r' || c == '\u0085' || c == '\u2028' || c == '\u2029';
    }

    /**
     * How many labels a host name has, as a certificate's names are compared: its dot-separated parts, empty ones at
     * its end aside.
     */
    static int labels(String host) {
        if (host.indexOf('.') < 0) return 1;
        int end = host.length();
        while (end > 0 && host.charAt(end - 1) == '.') end--;
        int n = end == 0 ? 0 : 1;
        for (int i = 0; i < end; i++) if (host.charAt(i) == '.') n++;
        return n;
    }

    /**
     * Whether a host is an address rather than a name (dots and digits, or an IPv6 address's colons): a handshake sends
     * it no name.
     */
    static boolean isAddress(String host) {
        boolean digits = !host.isEmpty();
        boolean oneLine = true;
        for (char c : host.toCharArray()) {
            if (c != '.' && (c < '0' || c > '9')) digits = false;
            if (lineEnd(c)) oneLine = false;
        }
        return digits || oneLine && host.indexOf(':') >= 0;
    }

    /**
     * An address as an item names it: the path and query of one on the audited site or the base address, any other
     * whole.
     */
    static String asked(String address) {
        URI uri = URI.create(address);
        String host = bare(uri.getHost());
        boolean own = uri.getHost() != null
                && (host.equals(bare(URI.create(SiteConfig.CRAWLED_URL).getHost()))
                || host.equals(bare(URI.create(SiteConfig.baseUrl()).getHost())));
        return own ? uri.getRawPath() + (uri.getRawQuery() == null ? "" : "?" + uri.getRawQuery()) : address;
    }

    /** The certificate checks (SITE-26): one handshake each, as the crawl's probe made it. */
    static final class Certificates {
        private static final long DAY_MS = 24L * 60 * 60 * 1000;

        private Certificates() {}

        /** What the certificate shows: open, fixed or cannot, and in words. */
        static String[] seen(String host, int port, String open, int days) {
            if (behindProxy()) return new String[] {"cannot", "behind a proxy: the run reaches the site through it"};
            URI base = URI.create(SiteConfig.baseUrl());
            if (!bare(base.getHost()).equals(bare(host))) {
                if (!"https".equalsIgnoreCase(base.getScheme())) return new String[] {"cannot", "the run's address, "
                        + SiteConfig.baseUrl() + ", has no certificate to read"};
                host = base.getHost();
                port = base.getPort() < 0 ? 443 : base.getPort();
            }
            try {
                if (open.equals("trust")) return trustSeen(host, port);
                X509Certificate cert = peer(host, port);
                return open.equals("expiry") ? expirySeen(cert, days) : nameSeen(cert, host);
            } catch (IOException | GeneralSecurityException e) {
                return new String[] {"cannot", "no handshake with " + host + ":" + port + " (" + e.getClass()
                        .getSimpleName() + ")"};
            }
        }

        private static String[] expirySeen(X509Certificate cert, int days) {
            Instant end = cert.getNotAfter().toInstant();
            long left = Math.floorDiv(end.toEpochMilli() - System.currentTimeMillis(), DAY_MS);
            String on = end.truncatedTo(ChronoUnit.DAYS).toString().substring(0, 10);
            return left < days ? new String[] {"open", left < 0 ? "ended on " + on : "ends on " + on + ", " + left
                    + " days from now"} : new String[] {"fixed", "ends on " + on + ", " + left + " days from now"};
        }

        private static String[] nameSeen(X509Certificate cert, String host) throws GeneralSecurityException {
            List<String> names = new ArrayList<>();
            if (cert.getSubjectAlternativeNames() != null) for (List<?> n : cert.getSubjectAlternativeNames()) if (
                    Integer.valueOf(2).equals(n.get(0))) names.add(String.valueOf(n.get(1)));
            boolean covered = names.stream()
                    .anyMatch(name -> name.equalsIgnoreCase(host)
                    || (name.startsWith("*.") && host.toLowerCase(Locale.ROOT)
                    .endsWith(name.substring(1).toLowerCase(Locale.ROOT)) && labels(host) == labels(name)));
            return new String[] {covered ? "fixed" : "open", "is for "
                    + (names.isEmpty() ? "no name" : String.join(", ", names))
                    + (covered ? ", " + host + " among them" : ", not " + host)};
        }

        private static String[] trustSeen(String host, int port) throws IOException, GeneralSecurityException {
            try {
                handshake(SSLContext.getDefault(), host, port).close();
                return new String[] {"fixed", "trusted by this machine's certificate authorities"};
            } catch (javax.net.ssl.SSLHandshakeException e) {
                return new String[] {"open", "not trusted: " + e.getMessage()};
            }
        }

        /** One handshake with the host, its name sent (SNI), under the context's trust. */
        private static SSLSocket handshake(SSLContext context, String host, int port) throws IOException {
            SSLSocket socket = (SSLSocket) context.getSocketFactory().createSocket();
            try {
                socket.connect(new InetSocketAddress(host, port), 15000);
                socket.setSoTimeout(15000);
                javax.net.ssl.SSLParameters named = socket.getSSLParameters();
                if (!isAddress(host)) named.setServerNames(List.of(new javax.net.ssl.SNIHostName(host)));
                socket.setSSLParameters(named);
                socket.startHandshake();
                return socket;
            } catch (IOException e) {
                socket.close();
                throw e;
            }
        }

        /** The certificate the host presents, read whatever its trust (the crawl's probe read it so too). */
        private static X509Certificate peer(String host, int port) throws IOException, GeneralSecurityException {
            SSLContext any = SSLContext.getInstance("TLS");
            any.init(null, new TrustManager[] {new X509TrustManager() {
                @Override public void checkClientTrusted(X509Certificate[] chain, String auth) {}
                @Override public void checkServerTrusted(X509Certificate[] chain, String auth) {}
                @Override public X509Certificate[] getAcceptedIssuers() { return new X509Certificate[0]; }
            }}, null);
            try (SSLSocket socket = handshake(any, host, port)) {
                return (X509Certificate) socket.getSession().getPeerCertificates()[0];
            }
        }
    }

    /** A redirect within the site: to the address asked's own host, or to the audited site's. */
    private static boolean within(URI asked, String to) {
        String host = asked.resolve(to).getHost();
        return host != null
                && (host.equalsIgnoreCase(asked.getHost()) || bare(host)
                .equals(bare(URI.create(SiteConfig.CRAWLED_URL).getHost())));
    }

    private static String bare(String host) {
        String h = host == null ? "" : host.toLowerCase(Locale.ROOT);
        return h.startsWith("www.") ? h.substring(4) : h;
    }

    /**
     * One request, redirects not followed. A path is asked on the suite's base address; the audited site's own address
     * whole
     * (its http address, say) is asked on the base address's host instead, so a run against staging asks staging.
     */
    static HttpResponse<Void> ask(String address) throws IOException, InterruptedException {
        return HTTP.send(request(address), HttpResponse.BodyHandlers.discarding());
    }

    /** The request for an address, asked as ask() says. */
    private static HttpRequest request(String address) {
        URI uri = URI.create(address.startsWith("/") ? SiteConfig.url(address) : address);
        URI base = URI.create(SiteConfig.baseUrl());
        if (!address.startsWith("/") && bare(uri.getHost()).equals(bare(URI.create(SiteConfig.CRAWLED_URL).getHost()))
                && !bare(base.getHost()).equals(bare(uri.getHost()))) {
            uri = URI.create(uri.getScheme() + "://" + base.getRawAuthority() + uri.getRawPath()
                    + (uri.getRawQuery() == null ? "" : "?" + uri.getRawQuery()));
        }
        HttpRequest.Builder request = HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(30)).GET();
        String agent = System.getProperty("userAgent", "");
        if (!agent.isBlank()) request.header("User-Agent", agent);
        return request.build();
    }

    /** A file read, its redirects followed up to 5 as the crawl's probe did: its last answer, with its body. */
    private static HttpResponse<String> read(String address) throws IOException, InterruptedException {
        String at = address;
        for (int hop = 0; ; hop++) {
            HttpResponse<String> answer = HTTP.send(request(at),
                    HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
            String to = answer.headers().firstValue("location").orElse("");
            if (answer.statusCode() < 300 || answer.statusCode() >= 400 || to.isEmpty() || hop >= 5) return answer;
            at = answer.uri().resolve(to).toString();
        }
    }

    /**
     * Whether the run reaches the web through a proxy: a connection of its own to one address would say nothing of the
     * site.
     */
    private static boolean behindProxy() {
        for (String name : new String[] {"HTTPS_PROXY", "https_proxy", "HTTP_PROXY", "http_proxy"}) {
            String value = System.getenv(name);
            if (value != null && !value.isBlank()) return true;
        }
        return ProxySelector.getDefault().select(URI.create(SiteConfig.baseUrl())).stream()
                .anyMatch(p -> p.type() != Proxy.Type.DIRECT);
    }
}
